import numpy as np
import scipy.stats as st

def close(a, b, rtol: float = 1e-10) -> bool:
    x = np.asarray(a).astype(float).ravel()
    y = np.asarray(b).astype(float).ravel()
    if x.shape != y.shape:
        return False
    for i in range(x.shape[0]):
        u = float(x[i])
        v = float(y[i])
        if not (abs(u - v) <= 1e-12 + rtol * abs(v) or (u != u and v != v)):
            print('mismatch', i, u, v)
            return False
    return True

x = [3.1, 1.4, 5.9, 2.6, 5.3, 5.8, 9.7, 9.3, 2.3, 8.4]
w = [1.0, 2.0, 1.0, 3.0, 1.0, 2.0, 1.0, 1.0, 2.0, 1.0]
ps = [0.0, 0.1, 0.33, 0.5, 0.77, 1.0]

@test
def test_quantile():
    assert close(st.quantile(x, ps, method='inverted_cdf'), [1.4, 1.4, 3.1, 5.3, 8.4, 9.7])
    assert close(st.quantile(x, ps, method='averaged_inverted_cdf'), [1.4, 1.8499999999999999, 3.1, 5.55, 8.4, 9.7])
    assert close(st.quantile(x, ps, method='closest_observation'), [1.4, 1.4, 2.6, 5.3, 8.4, 9.7])
    assert close(st.quantile(x, ps, method='hazen'), [1.4, 1.8499999999999999, 3.0, 5.55, 8.58, 9.7])
    assert close(st.quantile(x, ps, method='interpolated_inverted_cdf'), [1.4, 1.4, 2.75, 5.3, 7.65, 9.7])
    assert close(st.quantile(x, ps, method='linear'), [1.4, 2.21, 3.085, 5.55, 8.225, 9.7])
    assert close(st.quantile(x, ps, method='median_unbiased'), [1.4, 1.73, 2.971666666666667, 5.55, 8.661000000000001, 9.7])
    assert close(st.quantile(x, ps, method='normal_unbiased'), [1.4, 1.7599999999999998, 2.9787500000000002, 5.55, 8.64075, 9.7])
    assert close(st.quantile(x, ps, method='weibull'), [1.4, 1.49, 2.9150000000000005, 5.55, 8.823, 9.7])
    assert close(st.quantile(x, ps, method='harrell-davis'), [1.4, 1.8271387642831125, 3.5237413667987982, 5.196437317987694, 8.17598610663292, 9.7])
    assert close(st.quantile(x, ps, method='_lower'), [1.4, 1.4, 2.6, 5.3, 5.9, 9.7])
    assert close(st.quantile(x, ps, method='_midpoint'), [1.4, 1.8499999999999999, 2.85, 5.55, 7.15, 9.7])
    assert close(st.quantile(x, ps, method='_higher'), [1.4, 2.3, 3.1, 5.8, 8.4, 9.7])
    assert close(st.quantile(x, ps, method='_nearest'), [1.4, 2.3, 3.1, 5.3, 8.4, 9.7])
    assert close(st.quantile(x, ps, method='round_outward'), [1.4, 2.3, 3.1, 5.3, 8.4, 9.7])
    assert close(st.quantile(x, ps, method='round_inward'), [1.4, 2.3, 5.3, 5.3, 5.9, 9.7])
    assert close(st.quantile(x, ps, method='round_nearest'), [1.4, 2.3, 3.1, 5.3, 8.4, 9.7])
    assert close(st.quantile(x, ps, method='inverted_cdf', weights=w), [1.4, 1.4, 2.6, 3.1, 5.9, 9.7])
    assert close(st.quantile(x, ps, method='averaged_inverted_cdf', weights=w), [1.4, 1.4, 2.6, 3.1, 5.9, 9.7])
    assert close(st.quantile(x, ps, method='closest_observation', weights=w), [1.4, 1.4, 2.6, 3.1, 5.9, 9.7])
    assert close(st.quantile(x, ps, method='hazen', weights=w), [1.4, 1.4, 2.6, 3.1, 6.025000000000002, 9.7])
    assert close(st.quantile(x, ps, method='linear', weights=w), [1.4, 1.7599999999999998, 2.6, 3.1, 5.878000000000001, 9.7])
    assert close(st.quantile(x, ps, method='weibull', weights=w), [1.4, 1.4, 2.6, 3.1, 6.700000000000001, 9.7])
    X = np.array([[3.1, 8.4], [1.4, 2.3], [5.9, 9.3], [2.6, 9.7], [5.3, 5.8], [5.8, 5.3], [9.7, 2.6], [9.3, 5.9], [2.3, 1.4], [8.4, 3.1]])
    assert close(st.quantile(X, [0.25, 0.75], axis=0), [2.725, 7.775])
    assert close(st.quantile(X, 0.4, axis=0), [4.419999999999999, 4.419999999999999])

@test
def test_estimated_cdf():
    assert close(st.estimated_cdf(x, [0.5, 1.4, 3.0, 5.85, 9.7, 12.0], method='inverted_cdf'), [0.0, 0.1, 0.3, 0.6, 1.0, 1.0])
    assert close(st.estimated_cdf(x, [0.5, 1.4, 3.0, 5.85, 9.7, 12.0], method='averaged_inverted_cdf'), [0.0, 0.1, 0.3, 0.6, 1.0, 1.0])
    assert close(st.estimated_cdf(x, [0.5, 1.4, 3.0, 5.85, 9.7, 12.0], method='closest_observation'), [0.0, 0.15, 0.35, 0.65, 1.0, 1.0])
    assert close(st.estimated_cdf(x, [0.5, 1.4, 3.0, 5.85, 9.7, 12.0], method='hazen'), [0.0, 0.05, 0.32999999999999996, 0.5999999999999995, 0.95, 1.0])
    assert close(st.estimated_cdf(x, [0.5, 1.4, 3.0, 5.85, 9.7, 12.0], method='interpolated_inverted_cdf'), [0.0, 0.1, 0.38, 0.6499999999999996, 1.0, 1.0])
    assert close(st.estimated_cdf(x, [0.5, 1.4, 3.0, 5.85, 9.7, 12.0], method='linear'), [0.0, 0.0, 0.3111111111111111, 0.6111111111111106, 1.0, 1.0])
    assert close(st.estimated_cdf(x, [0.5, 1.4, 3.0, 5.85, 9.7, 12.0], method='median_unbiased'), [0.0, 0.06451612903225808, 0.33548387096774196, 0.5967741935483868, 0.935483870967742, 1.0])
    assert close(st.estimated_cdf(x, [0.5, 1.4, 3.0, 5.85, 9.7, 12.0], method='normal_unbiased'), [0.0, 0.06097560975609756, 0.3341463414634146, 0.5975609756097556, 0.9390243902439024, 1.0])
    assert close(st.estimated_cdf(x, [0.5, 1.4, 3.0, 5.85, 9.7, 12.0], method='weibull'), [0.0, 0.09090909090909091, 0.34545454545454546, 0.5909090909090905, 0.9090909090909091, 1.0])
